import * as React from 'react'
import { CircleCheck, CircleX, Info, TriangleAlert, X } from 'lucide-react'

import { cx } from '~/lib/cx'
import styles from './banner.module.scss'

export type BannerTone = 'info' | 'success' | 'warning' | 'danger'

const TONE = {
  info: { tone: styles.info, icon: Info },
  success: { tone: styles.success, icon: CircleCheck },
  warning: { tone: styles.warning, icon: TriangleAlert },
  danger: { tone: styles.danger, icon: CircleX },
} as const

export interface BannerProps {
  tone?: BannerTone
  title?: React.ReactNode
  children?: React.ReactNode
  action?: React.ReactNode
  dismissible?: boolean
  onDismiss?: () => void
  className?: string
}

export function Banner({
  tone = 'info',
  title,
  children,
  action,
  dismissible = false,
  onDismiss,
  className,
}: BannerProps) {
  const [visible, setVisible] = React.useState(true)

  if (!visible) return null

  const config = TONE[tone]
  const Icon = config.icon

  return (
    <div
      role={tone === 'danger' ? 'alert' : 'status'}
      className={cx(styles.root, config.tone, className)}
    >
      <Icon className={styles.icon} aria-hidden />
      <div className={styles.body}>
        {title ? <p className={styles.title}>{title}</p> : null}
        {children ? <div className={styles.content}>{children}</div> : null}
      </div>
      {action ? <div className={styles.action}>{action}</div> : null}
      {dismissible ? (
        <button
          type="button"
          onClick={() => {
            setVisible(false)
            onDismiss?.()
          }}
          aria-label="Dismiss banner"
          className={styles.dismiss}
        >
          <X aria-hidden />
        </button>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  --banner-bg: #{vz.color('info', 0.1)};
  --banner-border: #{vz.color('info', 0.3)};
  --banner-icon: #{vz.color('info')};

  display: flex;
  align-items: flex-start;
  gap: vz.space(3);
  padding: vz.space(3);
  border: 1px solid var(--banner-border);
  border-radius: vz.radius('lg');
  background: var(--banner-bg);
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
}

.info {
  --banner-bg: #{vz.color('info', 0.1)};
  --banner-border: #{vz.color('info', 0.3)};
  --banner-icon: #{vz.color('info')};
}

.success {
  --banner-bg: #{vz.color('success', 0.1)};
  --banner-border: #{vz.color('success', 0.3)};
  --banner-icon: #{vz.color('success')};
}

.warning {
  --banner-bg: #{vz.color('warning', 0.1)};
  --banner-border: #{vz.color('warning', 0.3)};
  --banner-icon: #{vz.color('warning')};
}

.danger {
  --banner-bg: #{vz.color('destructive', 0.1)};
  --banner-border: #{vz.color('destructive', 0.3)};
  --banner-icon: #{vz.color('destructive')};

  color: vz.color('destructive');
}

.icon {
  margin-top: 2px;
  color: var(--banner-icon);

  @include vz.icon(4);
}

.body {
  flex: 1;
  min-width: 0;
}

.title {
  margin: 0;
  font-weight: 500;
  line-height: 1.4;
}

.content {
  margin-top: 2px;
  opacity: 0.8;
}

.action {
  flex: none;
}

.dismiss {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: inherit;
  opacity: 0.7;
  cursor: pointer;
  transition: opacity vz.duration('fast') vz.ease('out');

  @include vz.hover {
    opacity: 1;
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    @include vz.icon(4);
  }
}
